{
"cards": [
{"key": "pc_kokkoro_harvest", "effectName": "든든한 준비", "keyword": "쌀 인벤토리·영구 성장·즉시 치료는 아니다", "canonFact": "미식전 쌀농사와 생활 지원을 든든한 준비·자원 정리로 각색."},
{"key": "pc_tsumugi_fit", "effectName": "움직임에 맞는 준비", "keyword": "실제 옷 장비·새 실 기술·호감 게이지는 생성하지 않는다", "canonFact": "공식 의상 가게와 아이돌의 활동을 움직임에 맞는 준비로 각색한다."},
{"key": "pc_kasumi_compare", "effectName": "개인 관통·정확한 일격", "keyword": "실제 조사 마법·적 방어 디버프·본편 진상을 지급하지 않는다", "canonFact": "자경단 조사 역할에서 서로 다른 흔적을 대조하는 준비를 개인 관통·정확한 일격으로 각색."},
{"key": "pc_monica_order", "effectName": "빠른 지시·방어 준비", "keyword": "원작 스킬 수치나 동료 버프·부대 NPC 생성은 아니다", "canonFact": "자칭 군인과 주민 보호 의뢰 소재를 빠른 지시·방어 준비로 각색."},
{"key": "pc_nozomi_step", "effectName": "일정한 움직임·든든한 준비", "keyword": "실제 공연·노래 스킬·즉시 회복·민심 변화는 없다", "canonFact": "카르미나 가수와 동료를 돕는 역할을 일정한 움직임·든든한 준비로 각색."}
],
"events": [
{
"key": "pc_rainy_harvest",
"story": "갑작스러운 폭우가 예고되어 논밭의 배수와 수확이 시급해졌다. 콧코로는 필요한 도구 리스트를 꼼꼼히 확인하며 효율적인 배수 작업을 제안한다.",
"intro": "비가 쏟아지기 전에 곡식을 옮겨야 한다.",
"choices": [
{"label": "도구를 빌려 콧코로와 배수부터 돕는다", "result": "도구 비용 220을 지불하고 콧코로의 안내에 따라 배수 작업을 시작한다. 배수 작업이 어느 정도 마무리되어 자원 정리 요령을 익힌다."},
{"label": "페코린느와 넓은 보급길까지 맡아 묶음을 옮긴다", "result": "페코린느와 함께 넓은 구역의 보급길을 담당하여 무거운 곡물 묶음을 운반한다. 이동 거리는 늘어났지만 많은 양의 곡식을 옮긴다."},
{"label": "좁은 구역의 정리만 돕고 일당과 물약을 받는다", "result": "가장 안전한 좁은 구역만 정리하고 작업을 마무리한다. 일당 150과 물약 1개를 받는다."}
]
},
{
"key": "pc_wrong_costume_tag",
"story": "츠무기의 가게에 배달된 옷의 이름표와 의뢰서의 수취인이 서로 일치하지 않는다. 유우키는 당황하며 종이를 확인하고 츠무기는 함부로 가위질을 하지 못한다.",
"intro": "배송지에 문제가 생겨 확인이 필요하다.",
"choices": [
{"label": "연락용품과 측정 도구를 마련해 츠무기와 의뢰를 맞춘다", "result": "연락용품과 측정 도구 비용 240을 지불하여 정확한 배송처를 확인한다. 츠무기와 협력하여 의뢰 정보를 재정리하는 요령을 배운다."},
{"label": "맞지 않는 옷은 돌려보내고 포장 일을 돕는다", "result": "잘못된 옷은 즉시 반송 처리하고 다른 상품의 포장 작업을 돕는다. 일당 180과 물약 1개를 받는다."}
]
},
{
"key": "pc_witness_hours",
"story": "카스미는 자경단으로부터 상반된 두 주민의 목격담을 전달받는다. 한 명은 수레를, 다른 한 명은 보행자를 보았으나 진술한 시각이 서로 어긋나 있다.",
"intro": "증언 사이의 모순을 찾아내야 한다.",
"choices": [
{"label": "기록 도구를 사서 카스미와 시각부터 대조한다", "result": "기록 도구 비용 220을 지불하여 카스미와 함께 시각 기록을 대조한다. 대조를 통해 흔적을 추적하는 개인 관통의 요령을 얻는다."},
{"label": "확인할 길목을 줄이고 보급품을 다시 묶는다", "result": "조사 범위를 좁히는 대신 보급품을 재포장한다. 비용 100을 지불하고 물약 2개를 받는다."},
{"label": "확인된 문장만 옮겨 적고 기록 보수를 받는다", "result": "확실한 진술만 골라 기록지에 옮겨 적는다. 기록 보수로 170을 받는다."}
]
},
{
"key": "pc_monica_market_watch",
"story": "주민의 안전이 위협받자 상점들이 일찍 문을 닫으려 한다. 모니카는 지킬 길목을 정하자고 제안하고 캬루는 넓은 구역을 맡는 것에 대해 우려를 표한다.",
"intro": "상점가 주변의 경계 순찰을 계획해야 한다.",
"choices": [
{"label": "표시 도구를 사서 모니카와 맡을 순서를 맞춘다", "result": "표시 도구 비용 240을 지불하여 모니카와 효율적인 순찰 동선을 짠다. 빠른 지시와 방어 준비 요령을 익힌다."},
{"label": "캬루와 더 넓은 길목을 맡아 공격 준비를 챙긴다", "result": "캬루와 함께 넓은 구역을 담당하며 경계 태세를 갖춘다. 담당 구역이 넓어져 적수가 2명 늘어난다."},
{"label": "맡을 위험한 길을 줄이고 보급품을 다시 마련한다", "result": "위험 요소가 많은 길을 제외하고 보급품을 재정비한다. 비용 100을 지불하고 물약 1개를 받는다."},
{"label": "폐점 정리만 돕고 일당을 받는다", "result": "상점들의 폐점 정리를 돕고 작업을 마친다. 일당 170을 받는다."}
]
},
{
"key": "pc_delivery_divide",
"story": "유우키가 가져온 전할 짐과 미식전의 보급품이 섞여 수레에 실렸다. 첫 갈림길에 도달하자 누구의 짐을 먼저 처리할지 결정해야 한다.",
"intro": "수레의 짐을 효율적으로 나누어야 한다.",
"choices": [
{"label": "포장 비용을 내고 콧코로와 전달할 몫을 나눈다", "result": "포장 비용 260을 지불하고 콧코로와 협력하여 짐을 분류한다. 세심한 준비 요령을 얻어 다음 전투를 준비한다."},
{"label": "페코린느와 큰 짐과 넓은 길목을 함께 맡는다", "result": "페코린느와 함께 무거운 짐을 들고 넓은 길을 이동한다. 동료와 몫을 나누는 준비를 하고 적수가 1명 늘어난다."},
{"label": "내가 맡을 구역만 줄이고 짐 분류 보수를 받는다", "result": "담당 구역을 줄이는 대신 짐을 분류하는 업무를 수행한다. 비용 없이 짐 분류 보수로 160을 받는다."}
]
},
{
"key": "pc_rehearsal_wall",
"story": "카르미나의 연습 장소에 쌓인 짐이 인근 주민들의 휴식 공간을 막고 있다. 노조미는 연습 준비를 하면서도 주민들의 불편을 최소화하기 위해 상황을 살핀다.",
"intro": "연습 공간과 주민들의 휴식 공간을 정리해야 한다.",
"choices": [
{"label": "완충재를 마련하고 노조미와 움직일 자리를 맞춘다", "result": "완충재 비용 200을 지불하고 노조미와 협력하여 짐을 옮긴다. 일정한 움직임과 든든한 준비 요령을 얻는다."},
{"label": "페코린느와 바깥 길까지 맡아 짐을 옮긴다", "result": "페코린느와 함께 더 먼 거리까지 짐을 운반한다. 이동 거리가 늘어나 적수가 1명 늘어난다."},
{"label": "짐 정리만 돕고 일당과 물약을 받는다", "result": "좁은 범위의 짐 정리만 도와주고 작업을 마친다. 일당 130과 물약 1개를 받는다."}
]
}
]
}
